import java.io.*;

public class Perturbed4 {
    static final int MOD = 998244353;

    public static void main(String[] args) throws Exception {
        FastReader fr = new FastReader();
        int n = fr.nextInt();
        long k = fr.nextLong();
        if (k >= n) {
            System.out.println(0);
            return;
        }
        long[] fac = new long[n + 1];
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = fac[i - 1] * i % MOD;
        }
        if (k == 0) {
            System.out.println(fac[n]);
            return;
        }
        int c = n - (int) k;
        long ans = fac[n] * modPow(fac[c], MOD - 2) % MOD;
        ans = ans * modPow(fac[n - c], MOD - 2) % MOD;
        long tem = 0;
        for (int i = 0; i <= c; i++) {
            long comb = fac[c] * modPow(fac[i], MOD - 2) % MOD;
            comb = comb * modPow(fac[c - i], MOD - 2) % MOD;
            long term = comb * modPow(c - i, n) % MOD;
            tem = (tem + (i % 2 == 0 ? term : MOD - term)) % MOD;
        }
        ans = ans * tem % MOD * 2 % MOD;
        System.out.println(ans);
    }

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = (res * a) % MOD;
            a = (a * a) % MOD;
            e >>= 1;
        }
        return res;
    }

    static class FastReader {
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        public FastReader() {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public int nextInt() throws Exception {
            int ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (neg) return -ret;
            return ret;
        }

        public long nextLong() throws Exception {
            long ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (neg) return -ret;
            return ret;
        }

        private byte read() throws Exception {
            if (bufferPointer == bytesRead) {
                bytesRead = din.read(buffer, 0, BUFFER_SIZE);
                bufferPointer = 0;
            }
            return buffer[bufferPointer++];
        }
    }
}
